    const totalMs = parseNum("LOCAL_LLM_TIMEOUT_MS") ?? defaultTotal;
    return new StreamWatchdog(firstByteMs, idleMs, totalMs, operatorSignal);
  }

  public setTaskId(taskId?: string): void {
    this.taskId = taskId;
  }
